#[path = "solution.rs"]
mod solution;

use solution::{apply_actions, parse_action, solve, ActionParseError, ApplyError, GameState};

#[test]
fn parses_only_the_two_exact_action_spellings() {
    assert!(matches!(parse_action("remove:1"), Ok(action) if action.0 == 1));
    assert!(matches!(parse_action("remove:2"), Ok(action) if action.0 == 2));

    for malformed in ["", "remove", "remove:", " remove:1", "remove:1 ", "REMOVE:1", "remove:+1", "remove:01"] {
        assert!(matches!(parse_action(malformed), Err(ActionParseError::Malformed)));
    }
    assert!(matches!(parse_action("remove:0"), Err(ActionParseError::UnsupportedAmount)));
    assert!(matches!(parse_action("remove:3"), Err(ActionParseError::UnsupportedAmount)));
}

#[test]
fn applies_valid_actions_and_alternates_turns() {
    let actions = ["remove:2", "remove:1"];
    let state = match apply_actions(5, &actions) {
        Ok(state) => state,
        Err(_) => panic!("valid sequence was rejected"),
    };
    assert_eq!(state.tokens, 2);
    assert!(state.first_players_turn);
    assert_eq!(actions, ["remove:2", "remove:1"]);
}

#[test]
fn apply_reports_invalid_action_indices() {
    assert!(matches!(apply_actions(3, &["remove:1", "bad"]), Err(ApplyError::InvalidAction { index: 1 })));
    assert!(matches!(apply_actions(1, &["remove:2"]), Err(ApplyError::InvalidAction { index: 0 })));
    assert!(matches!(apply_actions(2, &["remove:1", "remove:2"]), Err(ApplyError::InvalidAction { index: 1 })));
}

#[test]
fn actions_after_finished_game_are_distinguished() {
    assert!(matches!(apply_actions(1, &["remove:1", "remove:1"]), Err(ApplyError::ActionAfterFinish { index: 1 })));
    assert!(matches!(apply_actions(0, &["remove:1"]), Err(ApplyError::ActionAfterFinish { index: 0 })));

    let state = match apply_actions(0, &[]) {
        Ok(state) => state,
        Err(_) => panic!("empty sequence should be valid"),
    };
    assert_eq!(state.tokens, 0);
    assert!(state.first_players_turn);
}

#[test]
fn solver_handles_terminal_winning_and_losing_positions() {
    let terminal = solve(GameState { tokens: 0, first_players_turn: false });
    assert!(terminal.action.is_none());
    assert!(terminal.score < 0);
    assert!(terminal.cached_positions >= 1);

    let one = solve(GameState { tokens: 1, first_players_turn: true });
    assert!(matches!(one.action, Some(action) if action.0 == 1));
    assert!(one.score > 0);

    let two = solve(GameState { tokens: 2, first_players_turn: false });
    assert!(matches!(two.action, Some(action) if action.0 == 2));
    assert!(two.score > 0);

    let three = solve(GameState { tokens: 3, first_players_turn: true });
    assert!(matches!(three.action, Some(action) if action.0 == 1));
    assert!(three.score < 0);

    let four = solve(GameState { tokens: 4, first_players_turn: true });
    assert!(matches!(four.action, Some(action) if action.0 == 1));
    assert!(four.score > 0);
    assert!(four.cached_positions >= 4);
}

#[test]
fn solving_is_deterministic_and_does_not_mutate_supplied_state() {
    let state = GameState { tokens: 7, first_players_turn: false };
    let first = solve(GameState { tokens: state.tokens, first_players_turn: state.first_players_turn });
    let second = solve(GameState { tokens: state.tokens, first_players_turn: state.first_players_turn });

    assert_eq!(state.tokens, 7);
    assert!(!state.first_players_turn);
    assert_eq!(first.action.map(|a| a.0), second.action.map(|a| a.0));
    assert_eq!(first.score, second.score);
    assert_eq!(first.cached_positions, second.cached_positions);
}

